\title{A Characterization of the Aharoni--Korman Property via Saturated Chains:\\
Structural Lemmas and a Refutation of the Obstruction Direction}
\author{Aristotle}
\date{2026-07-06}

\begin{document}
\maketitle

\begin{abstract}
The \emph{Aharoni--Korman conjecture} (the \emph{fishbone conjecture}) asserts
that every partially ordered set with no infinite antichain contains a chain
meeting every maximal antichain. A natural strategy for the countable case is to
seek a concrete structural obstruction whose absence characterizes the property.
This paper studies one such proposal: that a countable poset satisfying the
finite antichain condition has the fishbone property \emph{if and only if} it
contains no saturated chain $D$ such that $D$ or its order dual is a countable
direct sum of infinite co-wellfounded posets. We make three contributions.
First, we develop the structural foundations: every infinite co-wellfounded
chain contains an infinite strictly descending sequence (a \emph{Descent
Theorem}, via Erd\H{o}s--Szekeres), a linear order that is simultaneously
well-founded and co-wellfounded is finite, and a countably infinite disjoint sum
of nonempty posets is never FAC. Second, we record the easy positive facts:
every chain is FAC, and every nonempty chain has the fishbone property. Third,
and centrally, we \emph{refute the obstruction direction}: the lexicographic sum
$\sum_{k\in\N}\Nop$ of countably many copies of the reversed naturals is a
countable FAC poset that \emph{is} the proposed obstruction and yet satisfies the
fishbone property. Hence the proposed ``if and only if'' fails as stated; we
isolate precisely why, and explain that the reverse implication remains an open
form of the conjecture.
\end{abstract}

\section{Introduction}

\subsection{Chains and antichains}
Let $(P,\le)$ be a partially ordered set (\textbf{poset}). A subset
$C\subseteq P$ is a \textbf{chain} if it is totally ordered by $\le$, and a
subset $A\subseteq P$ is an \textbf{antichain} if its elements are pairwise
incomparable. A poset satisfies the \textbf{finite antichain condition} (is
\textbf{FAC}) if every antichain is finite.

\subsection{The Aharoni--Korman conjecture}
An antichain $A$ is \textbf{maximal} if no antichain properly contains it.

\begin{quote}
\textbf{Aharoni--Korman conjecture (fishbone conjecture).} Every FAC poset
contains a chain $C$ that meets every maximal antichain, i.e.
$A\cap C\neq\varnothing$ for every maximal antichain $A$.
\end{quote}

We say such a poset \textbf{satisfies AK}. A chain cannot meet \emph{every}
antichain (e.g.\ the empty one), so the faithful reading uses maximal antichains,
which we adopt throughout.

\subsection{The proposed characterization}
\begin{quote}
\textbf{Proposed characterization.} A countable FAC poset $P$ satisfies AK if and
only if $P$ does not contain a saturated chain $D$ such that $D$ or its order
dual $D^{\op}$ is a countable direct sum of infinite co-wellfounded posets.
\end{quote}

We call $P$ an \textbf{AK obstruction} when it contains such a chain. The
characterization splits into the \emph{obstruction direction} (AK obstruction
$\Rightarrow$ not AK) and the \emph{reverse direction} (not AK obstruction
$\Rightarrow$ AK). Our central result is that the obstruction direction is false;
the reverse direction remains open.

\section{Definitions}

\begin{definition}[FAC]
A poset $P$ is \textbf{FAC} if every antichain $A\subseteq P$ is finite.
\end{definition}

\begin{definition}[Maximal antichain]
An antichain $A\subseteq P$ is \textbf{maximal} if for every antichain $B$ with
$A\subseteq B$ we have $A=B$.
\end{definition}

\begin{definition}[Satisfies AK]
$P$ \textbf{satisfies AK} if there is a chain $C\subseteq P$ with
$A\cap C\neq\varnothing$ for every maximal antichain $A$.
\end{definition}

\begin{definition}[Co-wellfounded]
$(\alpha,<)$ is \textbf{well-founded} if $<$ is well-founded, and
\textbf{co-wellfounded} if $>$ is well-founded (no infinite strictly ascending
sequence). The reversed naturals $\Nop=(\cdots<3<2<1<0)$ are the canonical
infinite co-wellfounded chain.
\end{definition}

\begin{definition}[Direct/lexicographic sum]
Given a linearly ordered index set $(\iota,\le)$ and linear orders $f(i)$, the
\textbf{direct sum} $\sum_{i\in\iota} f(i)$ has underlying set
$\{(i,x):i\in\iota,\ x\in f(i)\}$ ordered by
\[ (i,x)\le(j,y)\iff i<j\ \text{ or }\ (i=j\text{ and }x\le_{f(i)}y). \]
A linear order $C$ \textbf{is a direct sum of} $f$ if $C\cong\sum_{i\in\iota}f(i)$.
\end{definition}

\begin{definition}[Countable direct sum of infinite co-wellfounded posets]
A linear order $C$ \textbf{is a countable direct sum of infinite co-wellfounded
posets} if there are a countable linearly ordered index set $\iota$ and linear
orders $\{f(i)\}_{i\in\iota}$, each infinite and co-wellfounded, with
$C\cong\sum_{i\in\iota}f(i)$.
\end{definition}

\begin{definition}[Saturated chain]
An order embedding $e:D\hookrightarrow P$ from a linear order $D$
\textbf{presents a saturated chain} if its image is a maximal chain: whenever
$x\in P$ satisfies ``$e(d)\le x$ or $x\le e(d)$'' for all $d\in D$, then $x=e(d)$
for some $d$.
\end{definition}

\begin{definition}[AK obstruction]
A countable FAC poset $P$ \textbf{is an AK obstruction} if there is a linear
order $D$ and an order embedding $e:D\hookrightarrow P$ presenting a saturated
chain such that $D$ or $D^{\op}$ is a countable direct sum of infinite
co-wellfounded posets.
\end{definition}

\section{Structural lemmas on co-wellfounded orders}

\begin{theorem}[Descent Theorem]\label{thm:descent}
Let $\alpha$ be an infinite linear order that is co-wellfounded. Then there is a
strictly antitone map $f:\N\to\alpha$; equivalently, $\alpha$ contains an
infinite strictly descending sequence.
\end{theorem}

\begin{proof}[Proof sketch]
Since $\alpha$ is infinite, fix an injection $g_0:\N\hookrightarrow\alpha$. By the
Erd\H{o}s--Szekeres / infinite Ramsey principle for monotone subsequences, there
is a strictly increasing $g:\N\to\N$ with $n\mapsto g_0(g(n))$ either weakly
increasing or weakly decreasing throughout. Injectivity of $g_0\circ g$ upgrades
weak to strict. A strictly increasing subsequence is an infinite ascending
sequence, forbidden by co-wellfoundedness; hence the subsequence is strictly
decreasing, giving the required $f=g_0\circ g$.
\end{proof}

\begin{theorem}[Finiteness Theorem]\label{thm:finite}
A linear order $\alpha$ that is both well-founded and co-wellfounded is finite.
\end{theorem}

\begin{proof}
Contrapositive. If $\alpha$ is infinite then by Theorem~\ref{thm:descent} it has
an infinite strictly descending sequence, contradicting well-foundedness. Hence
$\alpha$ is finite.
\end{proof}

\begin{remark}
Theorem~\ref{thm:finite} says a linear order is finite iff it forbids both
infinite ascent and infinite descent: finiteness equals boundedness in every
direction of infinity.
\end{remark}

\section{Width thresholds and the easy positive facts}

\begin{theorem}[Width threshold]\label{thm:width}
A disjoint sum of countably infinitely many nonempty posets --- where elements
from different summands are mutually incomparable --- is not FAC.
\end{theorem}

\begin{proof}
Choose $a_i\in P_i$ for each of the infinitely many summands. For $i\neq j$,
$a_i$ and $a_j$ lie in different summands, hence are incomparable, so the
transversal $\{a_i\}$ is an infinite antichain.
\end{proof}

\begin{theorem}\label{thm:chainFAC}
Every chain is FAC.
\end{theorem}
\begin{proof}
In a linear order any two distinct elements are comparable, so every antichain
has at most one element.
\end{proof}

\begin{theorem}\label{thm:chainAK}
Every nonempty chain satisfies AK.
\end{theorem}
\begin{proof}
Take $C=P$. Any maximal antichain $A$ has at most one element
(Theorem~\ref{thm:chainFAC}); maximality with $P\neq\varnothing$ forces $A=\{a\}$
with $a\in P=C$, so $A\cap C\neq\varnothing$.
\end{proof}

\section{The obstruction direction is false}

Consider $D=\sum_{k\in\N}\Nop$, the lexicographic sum along $\N$ of countably
many copies of $\Nop$: the set $\N\times\N$ with
\[ (k,n)\le(k',n')\iff k<k'\ \text{ or }\ (k=k'\text{ and }n\ge n'). \]

\begin{theorem}[Refutation of the obstruction direction]\label{thm:refute}
There is a countable FAC poset $P$ that is an AK obstruction and yet satisfies
AK. Consequently the implication ``AK obstruction $\Rightarrow$ not AK'' is
false, and the proposed characterization fails as stated.
\end{theorem}

\begin{proof}
Take $P=D$. It is countable (underlying set $\N\times\N$). It is FAC and
satisfies AK by Theorems~\ref{thm:chainFAC} and \ref{thm:chainAK} (it is a
nonempty chain). It is an AK obstruction: take $D=P$ and $e=\mathrm{id}_P$, whose
image is all of $P$ and hence vacuously a maximal chain, so $e$ presents a
saturated chain; and $D=\sum_{k\in\N}\Nop$ is a countable direct sum of the
infinite co-wellfounded orders $\Nop$. Thus $P$ is simultaneously countable,
FAC, an AK obstruction, and satisfies AK, contradicting the obstruction
direction.
\end{proof}

\subsection{Anatomy of the error}
The defect is that the definition of AK obstruction permits the obstructing
saturated chain to be the \emph{entire} poset. When $P$ is a chain, every
maximal antichain is a singleton (Theorem~\ref{thm:chainFAC}) and the whole
chain trivially meets it (Theorem~\ref{thm:chainAK}); there are no
cross-sectional antichains for the obstruction to spoil. The statement conflated
a chain acting as the whole ambient space with a chain threaded through a
genuinely two-dimensional poset. A repair must force the obstruction to interact
with nontrivial antichains, e.g.\ by requiring $P$ itself not to be a chain.

\subsection{What remains open}
The counterexample refutes only the obstruction direction. The reverse
direction --- if a countable FAC poset is not an AK obstruction then it satisfies
AK --- is not contradicted by any chain (chains always satisfy AK) and remains an
open form of the Aharoni--Korman conjecture for countable posets.

\section{Discussion and future directions}

\paragraph{1. Two-sided failure of welded co-wellfounded chains.} Welding
countably many infinite reverse-well-ordered chains end to end along $\N$ yields
a saturated chain whose ascending sequences live across the welding seams;
co-wellfoundedness being one-directional, gluing along a second direction
manufactures the missing ascent. Theorem~\ref{thm:descent} supplies the atomic
$\Nop$-copy such a gluing argument needs.

\paragraph{2. Additivity of FAC under finite direct sums.} Finitely many FAC
posets combine to an FAC poset whose maximum antichain size is the sum of the
parts', since any antichain of a disjoint combination splits over the parts. This
is the positive counterpart of Theorem~\ref{thm:width}.

\paragraph{3. A chain-or-antichain dichotomy.} Every infinite poset contains an
infinite chain or an infinite antichain, and a poset is finite iff it forbids
infinite ascent, infinite descent, and infinite antichains. Colouring pairs by
comparability turns the monotone-subsequence argument into infinite Ramsey;
Theorem~\ref{thm:finite} is the linear case.

\paragraph{4. Unique co-wellfounded segmentation of saturated chains.} Inside a
countable FAC poset, every saturated chain should break canonically into
consecutive well-founded or co-wellfounded segments, with the obstruction being
infinitely many infinite co-wellfounded segments.

\section{Conclusion}
We refuted the obstruction direction of a proposed characterization of the
countable Aharoni--Korman property: $\sum_{k\in\N}\Nop$ is a countable FAC poset
that is an AK obstruction yet satisfies AK. The refutation rests on elementary
facts about chains, supported by structural bedrock --- the Descent Theorem, the
Finiteness Theorem, and the Width Threshold --- that both explains the failure
and equips the corrected reverse direction, which remains open.

\end{document}

